import SwiftUI
import Charts

/// Animated chart transitions with physics-based animations
struct AnimatedChartContainer: View {\n    let chartData: ChartData\n    @Binding var selectedChartType: ChartType\n    \n    @State private var transactionScale: CGFloat = 0.8\n    @State private var rotationAngle: Double = 0\n    @State private var opacity: Double = 0\n    @State private var bounceEffect: Double = 0\n    @State private var particleEffect: Int = 0\n    \n    enum ChartType: String, CaseIterable, Identifiable {\n        case pie = \"pie\"\n        case bar = \"bar\" \n        case line = \"line\"\n        case area = \"area\"\n        case scatter = \"scatter\"\n        \n        var id: String { rawValue }\n        \n        var displayName: String {\n            switch self {\n            case .pie: return \"Pie Chart\"\n            case .bar: return \"Bar Chart\"\n            case .line: return \"Line Chart\"\n            case .area: return \"Area Chart\"\n            case .scatter: return \"Scatter Plot\"\n            }\n        }\n        \n        var transitionDuration: TimeInterval {\n            switch self {\n            case .pie: return 1.2\n            case .bar: return 0.8\n            case .line: return 1.0\n            case .area: return 1.1\n            case .scatter: return 0.9\n            }\n        }\n        \n        var animationCurve: Animation {\n            switch self {\n            case .pie: return .spring(response: 1.2, dampingFraction: 0.8, blendDuration: 0)\n            case .bar: return .easeInOut(duration: transitionDuration)\n            case .line: return .interactiveSpring(response: 1.0, dampingFraction: 0.9, blendDuration: 0)\n            case .area: return .spring(response: 1.1, dampingFraction: 0.85, blendDuration: 0)\n            case .scatter: return .easeInOut(duration: transitionDuration)\n            }\n        }\n    }\n    \n    var body: some View {\n        VStack(spacing: 16) {\n            // Chart type selector with visual feedback\n            chartTypeSelector\n            \n            // Animated chart container\n            ZStack {\n                // Background particles effect\n                particleOverlay\n                \n                // Main chart with physics animation\n                animatedChartView\n            }\n            .frame(height: 300)\n            .background(\n                RoundedRectangle(cornerRadius: 20)\n                    .fill(LinearGradient(\n                        gradient: Gradient(colors: [\n                            Color(.secondarySystemBackground),\n                            Color(.tertiarySystemBackground)\n                        ]),\n                        startPoint: .topLeading,\n                        endPoint: .bottomTrailing\n                    ))\n                    .shadow(\n                        color: .black.opacity(bounceEffect * 0.1),\n                        radius: 12 + bounceEffect * 20,\n                        x: 0,\n                        y: bounceEffect * 10\n                    )\n            )\n            .scaleEffect(transactionScale)\n            .rotationEffect(.degrees(rotationAngle))\n            .opacity(opacity)\n            .onChange(of: selectedChartType) { oldValue, newValue in\n                animateTransition(from: oldValue, to: newValue)\n            }\n        }\n        .onAppear {\n            enterAnimation()\n        }\n    }\n    \n    // MARK: - Chart Type Selector\n    \n    private var chartTypeSelector: some View {\n        ScrollView(.horizontal, showsIndicators: false) {\n            HStack(spacing: 12) {\n                ForEach(ChartType.allCases) { type in\n                    Button(action: {\n                        withAnimation(.easeInOut(duration: 0.3)) {\n                            selectedChartType = type\n                        }\n                    }) {\n                        VStack(spacing: 8) {\n                            Image(systemName: type.iconName)\n                                .font(.title3)\n                                .fontWeight(.medium)\n                                .foregroundColor(selectedChartType == type ? .white : chartColor(for: type))\n                            \n                            Text(type.displayName)\n                                .font(.caption)\n                                .fontWeight(.medium)\n                                .foregroundColor(selectedChartType == type ? .white : .primary)\n                                .lineLimit(1)\n                        }\n                        .padding(.horizontal, 16)\n                        .padding(.vertical, 12)\n                        .background(\n                            RoundedRectangle(cornerRadius: 16)\n                                .fill(\n                                    selectedChartType == type ?\n                                    chartColor(for: type) :\n                                    Color(.tertiarySystemBackground)\n                                )\n                                .shadow(\n                                    color: selectedChartType == type ? chartColor(for: type).opacity(0.3) : .clear,\n                                    radius: 8,\n                                    x: 0,\n                                    y: 4\n                                )\n                        )\n                        .scaleEffect(selectedChartType == type ? 1.05 : 1.0)\n                    }\n                    .buttonStyle(PlainButtonStyle())\n                }\n            }\n            .padding(.horizontal)\n        }\n    }\n    \n    // MARK: - Animated Chart View\n    \n    @ViewBuilder\n    private var animatedChartView: some View {\n        Group {\n            switch selectedChartType {\n            case .pie:\n                PieChartsView(chartData: chartData)\n            case .bar:\n                BarChartsView(chartData: chartData)\n            case .line:\n                LineChartsView(chartData: chartData)\n            case .area:\n                AreaChartsView(chartData: chartData)\n            case .scatter:\n                ScatterChartsView(chartData: chartData)\n            }\n        }\n        .scaleEffect(1.0 + bounceEffect * 0.1)\n    }\n    \n    // MARK: - Particle Overlay\n    \n    private var particleOverlay: some View {\n        ForEach(0..<particleEffect, id: \\.self) { index in\n            Circle()\n                .fill(chartColor(for: selectedChartType).opacity(0.3))\n                .frame(width: 2, height: 2)\n                .position(\n                    x: CGFloat.random(in: 0...300),\n                    y: CGFloat.random(in: 0...300)\n                )\n                .scaleEffect(particleEffect > 0 ? 1.0 : 0.0)\n                .animation(\n                    .easeOut(duration: Double.random(in: 0.5...1.5)),\n                    value: particleEffect\n                )\n        }\n    }\n    \n    // MARK: - Animation Methods\n    \n    private func enterAnimation() {\n        withAnimation(.spring(response: 0.8, dampingFraction: 0.9)) {\n            opacity = 1.0\n            transactionScale = 1.0\n        }\n        \n        withAnimation(.spring(response: 1.2, dampingFraction: 0.85).delay(0.2)) {\n            bounceEffect = 1.0\n        }\n        \n        DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {\n            withAnimation(.spring(response: 0.6, dampingFraction: 0.9)) {\n                bounceEffect = 0\n            }\n        }\n    }\n    \n    private func animateTransition(from oldType: ChartType, to newType: ChartType) {\n        // Particle explosion effect\n        withAnimation(.easeOut(duration: 0.5)) {\n            particleEffect = 20\n        }\n        \n        // Compression and expansion\n        withAnimation(.spring(response: 0.4, dampingFraction: 0.95)) {\n            transactionScale = 0.7\n            rotationAngle = oldType.rotationDifference(to: newType)\n        }\n        \n        // Bounce effect\n        withAnimation(.interactiveSpring(response: newType.transitionDuration, dampingFraction: 0.8).delay(0.2)) {\n            transactionScale = 1.1\n            rotationAngle = 0\n        }\n        \n        withAnimation(.spring(response: 0.6, dampingFraction: 0.9).delay(newType.transitionDuration + 0.2)) {\n            transactionScale = 1.0\n        }\n        \n        // Clear particles\n        DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {\n            withAnimation(.easeOut(duration: 0.5)) {\n                particleEffect = 0\n            }\n        }\n    }\n    \n    // MARK: - Helper Methods\n    \n    private func chartColor(for type: ChartType) -> Color {\n        switch type {\n        case .pie: return .orange\n        case .bar: return .blue\n        case .line: return .green\n        case .area: return .purple\n        case .scatter: return .red\n        }\n    }\n}\n\n// MARK: - Individual Chart Views\n\nstruct PieChartsView: View {\n    let chartData: ChartData\n    @State private var animatedAngle: Double = 0\n    \n    var body: some View {\n        Chart {\n            ForEach(Array(chartData.pieData.enumerated()), id: \\.offset) { index, data in\n                SectorMark(\n                    angle: .value(\"Amount\", data.value * animatedAngle),\n                    innerRadius: .ratio(0.4),\n                    angularInset: 2.0\n                )\n                .foregroundStyle(.byValue(\"Category\", data.category.name))\n            }\n        }\n        .chartLegend(position: .bottom)\n        .task {\n            withAnimation(.spring(response: 1.2, dampingFraction: 0.8)) {\n                animatedAngle = 1.0\n            }\n        }\n    }\n}\n\nstruct BarChartsView: View {\n    let chartData: ChartData\n    @State private var animatedHeight: Double = 0\n    \n    var body: some View {\n        Chart {\n            ForEach(Array(chartData.barData.enumerated()), id: \\.offset) { index, data in\n                BarMark(\n                    x: .value(\"Category\", data.category),\n                    y: .value(\"Amount\", data.value * animatedHeight)\n                )\n                .foregroundStyle(.byValue(\"Category\", data.category.name))\n                .cornerRadius(4)\n            }\n        }\n        .chartXAxis {\n            AxisMarks { value in\n                AxisGridLine()\n                AxisTick()\n                AxisValueLabel()\n            }\n        }\n        .task {\n            withAnimation(.interactiveSpring(response: 0.8, dampingFraction: 0.9, blendDuration: 0).delay(Double.random(in: 0...0.2))) {\n                animatedHeight = 1.0\n            }\n        }\n    }\n}\n\nstruct LineChartsView: View {\n    let chartData: ChartData\n    @State private var animatedDraw: Double = 0\n    \n    var body: some View {\n        Chart {\n            ForEach(Array(chartData.lineData.enumerated()), id: \\.offset) { index, data in\n                LineMark(\n                    x: .value(\"Point\", index),\n                    y: .value(\"Value\", data.value * animatedDraw)\n                )\n                .foregroundStyle(.blue)\n                .lineStyle(StrokeStyle(lineWidth: 3))\n                .symbol {\n                    Circle()\n                        .fill(.blue)\n                        .frame(width: 8, height: 8)\n                }\n            }\n        }\n        .task {\n            withAnimation(.easeInOut(duration: 1.0)) {\n                animatedDraw = 1.0\n            }\n        }\n    }\n}\n\nstruct AreaChartsView: View {\n    let chartData: ChartData\n    @State private var animatedFill: Double = 0\n    \n    var body: some View {\n        Chart {\n            ForEach(Array(chartData.lineData.enumerated()), id: \\.offset) { index, data in\n                AreaMark(\n                    x: .value(\"Point\", index),\n                    y: .value(\"Value\", data.value * animatedFill)\n                )\n                .foregroundStyle(\n                    LinearGradient(\n                        gradient: Gradient(colors: [.purple.opacity(0.6), .purple.opacity(0.1)]),\n                        startPoint: .top,\n                        endPoint: .bottom\n                    )\n                )\n            }\n        }\n        .task {\n            withAnimation(.spring(response: 1.1, dampingFraction: 0.85)) {\n                animatedFill = 1.0\n            }\n        }\n    }\n}\n\nstruct ScatterChartsView: View {\n    let chartData: ChartData\n    @State private var animatedPoints: Double = 0\n    \n    var body: some View {\n        Chart {\n            ForEach(Array(chartData.scatterData.enumerated()), id: \\.offset) { index, data in\n                PointMark(\n                    x: .value(\"X\", data.x),\n                    y: .value(\"Y\", data.y * animatedPoints)\n                )\n                .foregroundStyle(.red)\n                .symbolSize(animatedPoints * 50)\n            }\n        }\n        .task {\n            withAnimation(.easeInOut(duration: 0.9).delay(0.2)) {\n                animatedPoints = 1.0\n            }\n        }\n    }\n}\n\n// MARK: - Extensions\n\nextension AnimatedChartContainer.ChartType {\n    func iconName() -> String {\n        switch self {\n        case .pie: return \"chart.pie.fill\"\n        case .bar: return \"chart.bar.fill\"\n        case .line: return \"chart.line.uptrend.xyaxis\"\n        case .area: return \"chart.area\"\n        case .scatter: return \"chart.scatter\"\n        }\n    }\n    \n    func rotationDifference(to other: AnimatedChartContainer.ChartType) -> Double {\n        let allCases = AnimatedChartContainer.ChartType.allCases\n        let currentIndex = allCases.firstIndex(of: self) ?? 0\n        let otherIndex = allCases.firstIndex(of: other) ?? 0\n        return Double(otherIndex - currentIndex) * 45\n    }\n}\n\n// MARK: - Data Models\n\nstruct ChartData {\n    let pieData: [(category: Category, value: Double)]\n    let barData: [(category: String, value: Double)]\n    let lineData: [(value: Double)]\n    let scatterData: [(x: Double, y: Double)]\n    \n    init(pieData: [(Category, Double)] = [],\n         barData: [(String, Double)] = [],\n         lineData: [Double] = [],\n         scatterData: [(Double, Double)] = []) {\n        self.pieData = pieData\n        self.barData = barData\n        self.lineData = lineData\n        self.scatterData = scatterData\n    }\n}\n\n#Preview {\n    AnimatedChartContainer(\n        chartData: ChartData(\n            pieData: [\n                (Category(id: UUID(), name: \"Food\", isDefault: true), 3000),\n                (Category(id: UUID(), name: \"Transport\", isDefault: true), 2000),\n                (Category(id: UUID(), name: \"Entertainment\", isDefault: true), 1500)\n            ],\n            barData: [\n                (\"Food\", 3000),\n                (\"Transport\", 2000),\n                (\"Entertainment\", 1500)\n            ],\n            lineData: [1000, 1500, 1200, 1800, 2000],\n            scatterData: [\n                (1, 1000), (2, 1500), (3, 1200), (4, 1800), (5, 2000)\n            ]\n        ),\n        selectedChartType: .constant(.pie)\n    )\n}